 9	    static int binarySearch(int[] sortedValues, int target) {
10	        int lowerBound = 0;
11	        int upperBound = sortedValues.length - 1;
12	
13	        while (lowerBound <= upperBound) {
14	            int middleIndex = middleIndex(lowerBound, upperBound);
15	            int middleValue = sortedValues[middleIndex];
16	
17	            if (middleValue == target) {
18	                return middleIndex;
19	            }
20	
21	            if (middleValue < target) {
22	                lowerBound = middleIndex + 1;
23	            } else {
24	                upperBound = middleIndex - 1;
25	            }
26	        }
27	
28	        return NOT_FOUND;
29	    }
30	
31	    private static int middleIndex(int lowerBound, int upperBound) {
32	        return lowerBound + (upperBound - lowerBound) / 2;
33	    }
